                    const v = k.rl(e0);
                    const e1 = k.a[1];
                    k.a[1] +%= 4;
                    k.wl(e1, v);
                    k.logic(u32, v);
                }
                // $094b0  adda.l #$90, a1
                {
                    k.cy +%= 12;
                    k.a[1] +%= @as(u32, 0x90);
                }
                // $094b6  dbra d0, $194a8
                {
                    k.cy +%= 14;
                    const w = k.dv(u16, 0) -% 1;
                    k.setD(u16, 0, w);
                    if (w != 0xFFFF) { if (k.cy >= k.limit) return 0x194a8; continue :sw 0x194a8; }
                }
                // $094ba  suba.l #$23e, a0
                {
                    k.cy +%= 12;
                    k.a[0] -%= @as(u32, 0x23e);
                }
                // $094c0  dbra d1, $19472
                {
                    k.cy +%= 14;
                    const w = k.dv(u16, 1) -% 1;
                    k.setD(u16, 1, w);
                    if (w != 0xFFFF) { if (k.cy >= k.limit) return 0x19472; continue :sw 0x19472; }
                }
                // $094c4  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

